import pytest
from typing import List, Optional

def longest(strings: List[str]) -> Optional[str]:
    """ Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    >>> longest([])

    >>> longest(['a', 'b', 'c'])
    'a'
    >>> longest(['a', 'bb', 'ccc'])
    'ccc'
    """
    if not strings:
        return None

    maxlen = max(len(x) for x in strings)
    for s in strings:
        if len(s) == maxlen:
            return s

def test_longest_empty_list():
    assert longest([]) is None

def test_longest_single_element():
    assert longest(['hello']) == 'hello'

def test_longest_multiple_elements():
    assert longest(['a', 'bb', 'ccc']) == 'ccc'

def test_longest_same_length_returns_first():
    assert longest(['abc', 'def', 'ghi']) == 'abc'

def test_longest_with_different_lengths():
    assert longest(['short', 'very_long_string', 'medium']) == 'very_long_string'

